// lib/config.mjs — lê a configuração do ambiente (o "armário" do servidor).
// O código é o mesmo em todo lugar; o que muda é o ambiente.

export function carregarConfig(env) {
  const portaTexto = env.PORT ?? '3000';
  if (!/^\d+$/.test(portaTexto)) {
    throw new Error('porta invalida: ' + portaTexto);
  }
  const senha = env.DB_PASS;
  return {
    porta: Number(portaTexto),
    dbSenhaConfigurada: typeof senha === 'string' && senha.length > 0,
    ambiente: env.NODE_ENV ?? 'development',
  };
}

