// lib/log.mjs — logs estruturados: UMA linha de JSON por acontecimento.

// 2xx é info; 4xx é warn (quem errou foi quem chamou — 404 é aviso normal);
// 5xx é error (quebrou DENTRO do servidor, precisa investigar).
export function classificarNivel(status) {
  if (status >= 500) return 'error';
  if (status >= 400) return 'warn';
  return 'info';
}

export function registrarLog(level, msg, extras = {}, timestamp) {
  const niveis = ['info', 'warn', 'error'];
  if (!niveis.includes(level)) {
    throw new Error('level invalido: ' + level);
  }
  return JSON.stringify({
    level,
    msg,
    timestamp: timestamp ?? new Date().toISOString(),
    ...extras,
  });
}

