// lib/servidor.mjs — as rotas de produção: health check, log das respostas e o start.
import { carregarConfig } from './config.mjs';
import { classificarNivel, registrarLog } from './log.mjs';

// Health check: sem senha do banco configurada, o status é 'degradado' —
// o servidor responde, mas avisa que algo falta.
export function montarHealthCheck(env, agora) {
  const config = carregarConfig(env);
  return {
    status: config.dbSenhaConfigurada ? 'ok' : 'degradado',
    porta: config.porta,
    ambiente: config.ambiente,
    timestamp: agora,
  };
}

// Log estruturado de UMA resposta HTTP: o nível vem do status, a rota vai
// no contexto.
export function registrarResposta(status, rota, timestamp) {
  return registrarLog(classificarNivel(status), 'resposta', { status, rota }, timestamp);
}

// O comando oficial de start: sem ele, não há deploy.
export function scriptDeStart(packageJson) {
  const start = packageJson.scripts && packageJson.scripts.start;
  if (typeof start !== 'string' || start.length === 0) {
    throw new Error('script start ausente');
  }
  return start;
}

