import { test } from 'node:test';
import assert from 'node:assert/strict';
import { carregarConfig } from './lib/config.mjs';
import { classificarNivel, registrarLog } from './lib/log.mjs';
import { montarHealthCheck, registrarResposta, scriptDeStart } from './lib/servidor.mjs';

const AGORA = '2026-08-27T21:30:01.000Z';

test('carregarConfig converte a porta em numero, aplica defaults e valida', () => {
  const config = carregarConfig({ PORT: '8080', DB_PASS: 'segredo', NODE_ENV: 'production' });
  assert.deepEqual(config, { porta: 8080, dbSenhaConfigurada: true, ambiente: 'production' });
  assert.deepEqual(carregarConfig({}), { porta: 3000, dbSenhaConfigurada: false, ambiente: 'development' });
  assert.throws(() => carregarConfig({ PORT: 'abc' }), /porta/);
});

test('classificarNivel separa 2xx (info), 4xx (warn) e 5xx (error)', () => {
  assert.equal(classificarNivel(200), 'info');
  assert.equal(classificarNivel(404), 'warn');
  assert.equal(classificarNivel(500), 'error');
});

test('registrarLog monta uma linha JSON estruturada e valida o level', () => {
  const linha = JSON.parse(registrarLog('info', 'health check', { rota: '/health' }, AGORA));
  assert.deepEqual(linha, { level: 'info', msg: 'health check', rota: '/health', timestamp: AGORA });
  assert.throws(() => registrarLog('debug', 'mensagem', {}, AGORA), /level/);
});

test('montarHealthCheck reflete a configuracao do ambiente', () => {
  const ok = montarHealthCheck({ PORT: '8080', DB_PASS: 'segredo' }, AGORA);
  assert.deepEqual(ok, { status: 'ok', porta: 8080, ambiente: 'development', timestamp: AGORA });
  const degradado = montarHealthCheck({}, AGORA);
  assert.equal(degradado.status, 'degradado');
  assert.equal(degradado.porta, 3000);
});

test('registrarResposta gera o log da resposta HTTP com o nivel certo', () => {
  const erro = JSON.parse(registrarResposta(500, '/divide/0', AGORA));
  assert.deepEqual(erro, { level: 'error', msg: 'resposta', status: 500, rota: '/divide/0', timestamp: AGORA });
  const aviso = JSON.parse(registrarResposta(404, '/nao-existe', AGORA));
  assert.equal(aviso.level, 'warn');
});

test('scriptDeStart exige o comando oficial de start', () => {
  const packageJson = { name: 'dona-fina', scripts: { start: 'node servidor.mjs' } };
  assert.equal(scriptDeStart(packageJson), 'node servidor.mjs');
  assert.throws(() => scriptDeStart({ scripts: {} }), /start/);
  assert.throws(() => scriptDeStart({}), /start/);
});
